import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] ranges = new long[(int) n][2];
        for (int i = 0; i < ranges.length; i++) {
            for (int j = 0; j < ranges[i].length; j++) {
                ranges[i][j] = Long.parseLong(next());
            }
        }
        long lo = Long.parseLong(next());
        long hi = Long.parseLong(next());

        StringBuilder body = new StringBuilder();
        long total = 0;
        int i = 0;
        int count = (int) n;
        while (i < count && ranges[i][1] < lo) {
            body.append(ranges[i][0]).append(" ").append(ranges[i][1]).append("\n");
            total++;
            i++;
        }
        while (i < count && ranges[i][0] <= hi) {
            lo = Math.min(lo, ranges[i][0]);
            hi = Math.max(hi, ranges[i][1]);
            i++;
        }
        body.append(lo).append(" ").append(hi).append("\n");
        total++;
        while (i < count) {
            body.append(ranges[i][0]).append(" ").append(ranges[i][1]).append("\n");
            total++;
            i++;
        }
        System.out.println(total);
        System.out.print(body);
    }
}
